Cho phương trình ${- 4 x^{2} + \dfrac{16 x}{21} + \dfrac{16}{7}}=0$ có 2 nghiệm là $x_{1}; x_{2}$. Giá trị của biểu thức  $P=-5\cdot\left( x_{1}+x_{2} \right) +-4\cdot x_{1}\cdot x_{2}$ bằng $\dfrac{a}{b}$ với $(a;b)=1$ và $a \in \mathbb{Z}; b \in \mathbb{N} $. Tìm ${b}$.
\shortans{3}

\loigiai{
Theo định lí viet ta có\\
$x_{1}+x_{2}= \dfrac{4}{21} $\\
$x_{1} \cdot x_{2}= - \dfrac{4}{7} $\\
Vậy $P= - \dfrac{20}{21}+-4\cdot \left( - \dfrac{4}{7} \right)=  \dfrac{4}{3}$
}\end{ex}

\begin{ex}%[9D6V3-5]
Cho phương trình ${- 2 x^{2} - 4 x + 16}=0$ có 2 nghiệm là $x_{1}; x_{2}$. Giá trị của biểu thức  $P= \dfrac { -4x_{1}}{ x_{2}}+\dfrac { -4x_{2}}{ x_{1}}$ bằng $\dfrac{a}{b}$ với $(a;b)=1$ và $a \in \mathbb{Z}; b \in \mathbb{N} $. Tìm ${b}$.
\shortans{1}

\loigiai{
Theo định lí viet ta có\\
$x_{1}+x_{2}= -2 $\\
$x_{1} \cdot x_{2}= -8 $\\
$x_{1}^{2} + x_{2}^{2}= \left( x_{1}+x_{2} \right)^{2} -2 x_{1}x_{2} =\left( -2 \right)^{2} - 2 \cdot -8 = 20$\\
Vậy $P= \dfrac { -4x_{1}}{ x_{2}}+\dfrac { -4x_{2}}{ x_{1}}  =-4\cdot \dfrac {x_{1}^{2} + x_{2}^{2} }{x_{1} \cdot x_{2}} = 10$
}\end{ex}

